using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGBankTransactionDataAccess : IBankTransactionDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGBankTransactionDataAccess> _logger;
        private static string tableName = "bank_transactions";
        public PGBankTransactionDataAccess(IConfiguration config, ILogger<PGBankTransactionDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; " +
                    $"CREATE TABLE IF NOT EXISTS app.{tableName} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, householdId INT not null, fingerprint TEXT not null unique, occurredAt TIMESTAMPTZ not null, data jsonb not null); " +
                    $"CREATE INDEX IF NOT EXISTS {tableName}_household_idx ON app.{tableName} (householdId, occurredAt)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        public bool AddIfNew(BankTransaction transaction)
        {
            try
            {
                string cmd = $"INSERT INTO app.{tableName} (householdId, fingerprint, occurredAt, data) VALUES(@householdId, @fingerprint, @occurredAt, CAST(@data AS jsonb)) ON CONFLICT (fingerprint) DO NOTHING RETURNING id";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("householdId", transaction.HouseholdId);
                    ctext.Parameters.AddWithValue("fingerprint", transaction.Fingerprint);
                    ctext.Parameters.AddWithValue("occurredAt", DateTime.SpecifyKind(transaction.OccurredAtUtc, DateTimeKind.Utc));
                    ctext.Parameters.AddWithValue("data", "{}");
                    var id = ctext.ExecuteScalar();
                    if (id == null || id is DBNull)
                    {
                        return false;
                    }
                    transaction.Id = Convert.ToInt32(id);
                }
                string cmdU = $"UPDATE app.{tableName} SET data = CAST(@data AS jsonb) WHERE id = @id";
                using (var ctextU = pgDataSource.CreateCommand(cmdU))
                {
                    ctextU.Parameters.AddWithValue("id", transaction.Id);
                    ctextU.Parameters.AddWithValue("data", JsonSerializer.Serialize(transaction));
                    ctextU.ExecuteNonQuery();
                }
                return true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public List<BankTransaction> GetRecent(int householdId, int limit)
        {
            return Query($"SELECT data FROM app.{tableName} WHERE householdId = @householdId ORDER BY occurredAt DESC, id DESC LIMIT @limit",
                x => { x.AddWithValue("householdId", householdId); x.AddWithValue("limit", limit); });
        }
        public List<BankTransaction> GetSince(int householdId, DateTime fromUtc)
        {
            return Query($"SELECT data FROM app.{tableName} WHERE householdId = @householdId AND occurredAt >= @from ORDER BY occurredAt, id",
                x => { x.AddWithValue("householdId", householdId); x.AddWithValue("from", DateTime.SpecifyKind(fromUtc, DateTimeKind.Utc)); });
        }
        private List<BankTransaction> Query(string cmd, Action<NpgsqlParameterCollection> addParameters)
        {
            var results = new List<BankTransaction>();
            try
            {
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    addParameters(ctext.Parameters);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            var transaction = JsonSerializer.Deserialize<BankTransaction>(reader["data"] as string ?? "{}");
                            if (transaction != null)
                            {
                                results.Add(transaction);
                            }
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return results;
        }
    }
}
